import{c as t,Q as e,j as s,m as n}from"./chunks/framework.DOi4mjdC.js";const b=JSON.parse('{"title":"VectorPadding(ISASI)","description":"","frontmatter":{},"headers":[{"level":1,"title":"VectorPadding\\\\(ISASI\\\\)","slug":"vectorpaddingisasi"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/基础API/Memory矢量计算/数据填充/VectorPadding(ISASI).md","filePath":"api/SIMD-API/基础API/Memory矢量计算/数据填充/VectorPadding(ISASI).md"}'),d={name:"api/SIMD-API/基础API/Memory矢量计算/数据填充/VectorPadding(ISASI).md"};function l(p,a,i,o,r,c){return e(),s("div",null,[...a[0]||(a[0]=[n(`<h1 id="vectorpadding-isasi" tabindex="-1">VectorPadding(ISASI) <a class="header-anchor" href="#vectorpadding-isasi" aria-label="Permalink to &quot;VectorPadding\\(ISASI\\)&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>x</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>x</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>x</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>x</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>√</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>根据padMode（pad模式）与padSide（pad方向）对源操作数按照datablock进行填充操作。</p><p>假设源操作数的一个datablock有16个数，datablock[0:15]=a~p：</p><ul><li><p>padSide==false：从datablock的左边开始填充，即datablock的起始值方向(a-&gt;p)</p></li><li><p>padSide==true：从datablock的右边开始填充，即datablock的结束值方向(p-&gt;a)</p></li><li><p>padMode==0：用邻近数作为填充值，例：aaa|abc(padSide=false)、nop|ppp(padSide=true)</p></li><li><p>padMode==1：用邻近datablock值对称填充，例：cba|abc(padSide=false)、nop|pon(padSide=true)</p></li><li><p>padMode==2：用邻近datablock值填充，偏移一个数，做对称填充，例：</p><ul><li>padSide=false：xcb|abc，xcb被填充，填充过程描述：a被丢弃，对称填充，x处填充0</li><li>padSide=true：nop|onx，onx被填充，填充过程描述：p被丢弃，对称填充，x处填充0</li></ul></li></ul><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><ul><li><p>tensor前n个数据计算</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T&gt;</span></span>
<span class="line"><span>__aicore__ inline void VectorPadding(const LocalTensor&lt;T&gt;&amp; dst, const LocalTensor&lt;T&gt;&amp; src, const uint8_t padMode, const bool padSide, const uint32_t count)</span></span></code></pre></div></li><li><p>tensor高维切分计算</p><ul><li><p>mask逐bit模式</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T, bool isSetMask = true&gt;</span></span>
<span class="line"><span>__aicore__ inline void VectorPadding(const LocalTensor&lt;T&gt;&amp; dst, const LocalTensor&lt;T&gt;&amp; src, const uint8_t padMode, const bool padSide, const uint64_t mask[], const uint8_t repeatTime, const UnaryRepeatParams&amp; repeatParams)</span></span></code></pre></div></li><li><p>mask连续模式</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T, bool isSetMask = true&gt;</span></span>
<span class="line"><span>__aicore__ inline void VectorPadding(const LocalTensor&lt;T&gt;&amp; dst, const LocalTensor&lt;T&gt;&amp; src, const uint8_t padMode, const bool padSide, const uint64_t mask, const uint8_t repeatTime, const UnaryRepeatParams&amp; repeatParams)</span></span></code></pre></div></li></ul></li></ul><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>T</td><td>操作数数据类型。 Atlas 推理系列产品AI Core，支持的数据类型为：int16_t/uint16_t/half/int32_t/uint32_t/float</td></tr><tr><td>isSetMask</td><td>是否在接口内部设置mask。 true，表示在接口内部设置mask。false，表示在接口外部设置mask，开发者需要使用SetVectorMask接口设置mask值。这种模式下，接口入参中的mask值设置为占位符MASK_PLACEHOLDER，用于占位，无实际含义。</td></tr></tbody></table><p><strong>表 2</strong> 参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>dst</td><td>输出</td><td>目的操作数。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。 LocalTensor的起始地址需要32字节对齐。</td></tr><tr><td>src</td><td>输入</td><td>源操作数。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。 LocalTensor的起始地址需要32字节对齐。 源操作数的数据类型需要与目的操作数保持一致。</td></tr><tr><td>padMode</td><td>输入</td><td>padding模式，类型为uint8_t，取值范围：[0,2]。 0：用邻近数作为填充值。1：用邻近datablock值对称填充。2：用邻近datablock值填充，偏移一个数，做对称填充。</td></tr><tr><td>padSide</td><td>输入</td><td>padding的方向，类型为bool。 false：左边。true：右边。</td></tr><tr><td>count</td><td>输入</td><td>参与计算的元素个数。</td></tr><tr><td>mask[]/mask</td><td>输入</td><td>mask用于控制每次迭代内参与计算的元素。 逐bit模式：可以按位控制哪些元素参与计算，bit位的值为1表示参与计算，0表示不参与。 mask为数组形式，数组长度和数组元素的取值范围和操作数的数据类型有关。当操作数为16位时，数组长度为2，mask[0]、mask[1]∈[0, 264-1]并且不同时为0；当操作数为32位时，数组长度为1，mask[0]∈(0, 264-1]；当操作数为64位时，数组长度为1，mask[0]∈(0, 232-1]。 例如，mask=[8, 0]，8=0b1000，表示仅第4个元素参与计算。 连续模式：表示前面连续的多少个元素参与计算。取值范围和操作数的数据类型有关，数据类型不同，每次迭代内能够处理的元素个数最大值不同。当操作数为16位时，mask∈[1, 128]；当操作数为32位时，mask∈[1, 64]；当操作数为64位时，mask∈[1, 32]。</td></tr><tr><td>repeatTime</td><td>输入</td><td>重复迭代次数。矢量计算单元，每次读取连续的256Bytes数据进行计算，为完成对输入数据的处理，必须通过多次迭代（repeat）才能完成所有数据的读取与计算。repeatTime表示迭代的次数。 关于该参数的具体描述请参考高维切分API。</td></tr><tr><td>repeatParams</td><td>输入</td><td>控制操作数地址步长的参数。UnaryRepeatParams类型，包含操作数相邻迭代间相同DataBlock的地址步长，操作数同一迭代内不同DataBlock的地址步长等参数。 相邻迭代间的地址步长参数说明请参考repeatStride；同一迭代内DataBlock的地址步长参数说明请参考dataBlockStride。</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li><p>操作数地址对齐要求请参见<a href="./../../../通用说明和约束.html#section796754519912">通用地址对齐约束</a>。</p></li><li><p>mask仅控制目的操作数中的哪些元素要写入，源操作数的读取与mask无关。</p></li><li><p>count表示写入目的操作数中的元素总数，源操作数的读取与count无关。</p></li></ul><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><p>样例的srcLocal和dstLocal均为half类型。</p><p>更多样例可参考<a href="./../基础算术/更多样例-9.html">LINK</a>。</p><ul><li><p>tensor高维切分计算样例-mask连续模式</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>uint64_t mask = 256 / sizeof(half);</span></span>
<span class="line"><span>uint8_t padMode = 0;</span></span>
<span class="line"><span>bool padSide = false;</span></span>
<span class="line"><span>// repeatTime = 4, 128 elements one repeat, 512 elements total</span></span>
<span class="line"><span>// dstBlkStride, srcBlkStride = 1, no gap between blocks in one repeat</span></span>
<span class="line"><span>// dstRepStride, srcRepStride = 8, no gap between repeats</span></span>
<span class="line"><span>AscendC::VectorPadding(dstLocal, srcLocal, padMode, padSide, mask, 4, { 1, 1, 8, 8 });</span></span></code></pre></div></li><li><p>tensor高维切分计算样例-mask逐bit模式</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>uint64_t mask[2] = { UINT64_MAX, UINT64_MAX };</span></span>
<span class="line"><span>uint8_t padMode = 0;</span></span>
<span class="line"><span>bool padSide = false;</span></span>
<span class="line"><span>// repeatTime = 4, 128 elements one repeat, 512 elements total</span></span>
<span class="line"><span>// dstBlkStride, srcBlkStride = 1, no gap between blocks in one repeat</span></span>
<span class="line"><span>// dstRepStride, srcRepStride = 8, no gap between repeats</span></span>
<span class="line"><span>AscendC::VectorPadding(dstLocal, srcLocal, padMode, padSide, mask, 4, { 1, 1, 8, 8 });</span></span></code></pre></div></li><li><p>tensor前n个数据计算样例</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>uint8_t padMode = 0;</span></span>
<span class="line"><span>bool padSide = false;</span></span>
<span class="line"><span>AscendC::VectorPadding(dstLocal, srcLocal, padMode, padSide, 512);</span></span></code></pre></div></li></ul><p>结果示例如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 以srcLocal的一个datablock的值为例，有16个数</span></span>
<span class="line"><span>输入数据(srcLocal): [6.938 -8.86 -0.2263 ... 1.971 1.778]</span></span>
<span class="line"><span>输出数据(dstLocal): </span></span>
<span class="line"><span>[6.938 6.938 6.938 ... 6.938 6.938]</span></span></code></pre></div>`,24)])])}const u=t(d,[["render",l]]);export{b as __pageData,u as default};
